<h1><?= $kind==='mentors'?'مرشدها؛ صاحبان تجربه عملی':'تجربه‌ها؛ مسیر شناخت صاحب تجربه' ?></h1><p>تجربه را بشناس و برای گفت‌وگو با صاحب آن اقدام کن.</p>
<nav class="search-tabs section" aria-label="نوع جست‌وجو"><a class="secondary" href="<?= $this->h($this->url('/mentors?'.http_build_query(['q'=>$_GET['q']??'','term'=>$_GET['term']??'']))) ?>">مرشدها (<?= (int)$mentorTotal ?>)</a><a class="secondary" href="<?= $this->h($this->url('/experiences?'.http_build_query(['q'=>$_GET['q']??'','term'=>$_GET['term']??'']))) ?>">تجربه‌ها (<?= (int)$experienceTotal ?>)</a></nav><form method="get" class="card search-form"><?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="/<?= $this->h($kind) ?>"><?php endif; ?><label for="search">جست‌وجوی <?= $kind==='mentors'?'مرشد':'تجربه' ?></label><input id="search" name="q" value="<?= $this->h($_GET['q']??'') ?>" maxlength="160"><label for="term">موضوع یا مسئله</label><select id="term" name="term"><option value="">همه</option><?php foreach($terms as $t): ?><option value="<?= $this->h($t['id']) ?>" <?= ($_GET['term']??'')===$t['id']?'selected':'' ?>><?= $this->h($t['title']) ?></option><?php endforeach; ?></select><label for="sort">مرتب‌سازی</label><select id="sort" name="sort"><option value="relevant" <?= ($_GET['sort']??'relevant')==='relevant'?'selected':'' ?>>ارتباط با مسئله</option><option value="latest" <?= ($_GET['sort']??'')==='latest'?'selected':'' ?>>تازه‌ترین</option></select><?php if($kind==='experiences'): ?><details class="case-fields"><summary>فیلترهای بیشتر</summary><label>گروه هدف<input name="target_audience" value="<?= $this->h($_GET['target_audience']??'') ?>"></label><label>شرایط و محدودیت مشابه<input name="constraints" value="<?= $this->h($_GET['constraints']??'') ?>"></label><label>نوع نتیجه<select name="outcome"><option value="">همه نتایج</option><?php foreach(['success'=>'موفق','failure'=>'ناموفق','mixed'=>'ترکیبی','unknown'=>'نامشخص'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($_GET['outcome']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label></details><?php endif; ?><div class="search-actions"><button>جست‌وجو</button><a class="secondary" href="<?= $this->h($this->url('/'.$kind)) ?>">پاک کردن فیلترها</a></div></form>
<div class="grid3 section"><?php foreach(array_slice($rows,0,20) as $r): ?><article class="card"><span class="eyebrow"><?= $kind==='mentors'?'صاحب تجربه':'تجربه عملی' ?></span><h2><?= $this->h($r['title']??$r['display_name']) ?></h2><p><?= $this->h($r['headline']??$r['display_name']) ?></p><?php if(!empty($r['summary'])): ?><p class="card-summary"><?= $this->h($r['summary']) ?></p><?php endif; ?><a class="primary" href="<?= $this->h($this->url($kind==='mentors'?'/mentor/profile?id='.$r['user_id']:'/experience?id='.$r['id'])) ?>"><?= $kind==='mentors'?'شناخت مرشد و درخواست گفت‌وگو':'مطالعه و گفت‌وگو با صاحب تجربه' ?></a></article><?php endforeach; ?></div>
<?php if(!$rows): ?><p class="card">نتیجه‌ای پیدا نشد. واژه یا فیلتر دیگری انتخاب کنید.</p><?php endif; ?>
<div class="row section"><?php $p=max(1,(int)($_GET['page']??1));$filters=http_build_query(['q'=>$_GET['q']??'','term'=>$_GET['term']??'','target_audience'=>$_GET['target_audience']??'','constraints'=>$_GET['constraints']??'','outcome'=>$_GET['outcome']??'','sort'=>$_GET['sort']??'relevant']);if($p>1): ?><a href="<?= $this->h($this->url('/'.$kind.'?'.$filters.'&page='.($p-1))) ?>">صفحه قبل</a><?php endif;if(count($rows)>20): ?><a href="<?= $this->h($this->url('/'.$kind.'?'.$filters.'&page='.($p+1))) ?>">صفحه بعد</a><?php endif; ?></div>
